import AppKit
import Foundation
import UniformTypeIdentifiers

/// Reads the system pasteboard into a `ClipboardPayload`.
enum ClipboardReader {
    /// Pasteboard markers set by password managers and transient copies. Recording these
    /// would surprise users and, for password fields, leak secrets into a history file.
    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
    ]

    private static let maxTextBytes = 2 * 1024 * 1024
    private static let maxRichBytes = 4 * 1024 * 1024
    private static let maxImageBytes = 40 * 1024 * 1024

    static func read(from pasteboard: NSPasteboard) -> ClipboardPayload? {
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        if !types.isDisjoint(with: ignoredTypes) { return nil }

        let source = sourceAppName()
        if let file = filePayload(from: pasteboard, sourceApp: source) { return file }
        if let text = textPayload(from: pasteboard, sourceApp: source) { return text }
        if let image = imagePayload(from: pasteboard, sourceApp: source) { return image }
        return nil
    }

    // MARK: - Files

    private static func filePayload(from pasteboard: NSPasteboard, sourceApp: String?) -> ClipboardPayload? {
        guard pasteboard.types?.contains(.fileURL) == true else { return nil }
        let options: [NSPasteboard.ReadingOptionKey: Any] = [.urlReadingFileURLsOnly: true]
        guard let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: options) as? [URL],
              !urls.isEmpty else { return nil }

        // Keep the copy order: it is what Finder will paste. Only duplicate paths are removed.
        var seen = Set<String>()
        let paths = urls.map(\.path).filter { seen.insert($0).inserted }
        guard !paths.isEmpty else { return nil }

        let size = paths.reduce(0) { total, path in
            let attributes = try? FileManager.default.attributesOfItem(atPath: path)
            return total + ((attributes?[.size] as? NSNumber)?.intValue ?? 0)
        }
        return ClipboardPayload(
            kind: .files,
            filePaths: paths,
            sourceApp: sourceApp,
            byteCount: size
        )
    }

    // MARK: - Text

    private static func textPayload(from pasteboard: NSPasteboard, sourceApp: String?) -> ClipboardPayload? {
        let plain = pasteboard.string(forType: .string)
        let rtf = pasteboard.data(forType: .rtf)
        let html = pasteboard.data(forType: .html)

        var text = plain
        if text == nil || text?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == true {
            text = attributedPlainText(rtfData: rtf) ?? attributedPlainText(htmlData: html)
        }
        guard let text, !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
        guard text.utf8.count <= maxTextBytes else { return nil }

        let richRTF = (rtf?.count ?? 0) <= maxRichBytes ? rtf : nil
        let richHTML = (html?.count ?? 0) <= maxRichBytes ? html : nil
        return ClipboardPayload(
            kind: .text,
            text: text,
            rtfData: richRTF,
            htmlData: richHTML,
            sourceApp: sourceApp,
            byteCount: text.utf8.count
        )
    }

    private static func attributedPlainText(rtfData: Data?) -> String? {
        guard let rtfData else { return nil }
        return try? NSAttributedString(
            data: rtfData,
            options: [.documentType: NSAttributedString.DocumentType.rtf],
            documentAttributes: nil
        ).string
    }

    private static func attributedPlainText(htmlData: Data?) -> String? {
        guard let htmlData else { return nil }
        return try? NSAttributedString(
            data: htmlData,
            options: [.documentType: NSAttributedString.DocumentType.html],
            documentAttributes: nil
        ).string
    }

    // MARK: - Images

    private static func imagePayload(from pasteboard: NSPasteboard, sourceApp: String?) -> ClipboardPayload? {
        let png: Data?
        if let direct = pasteboard.data(forType: .png) {
            png = direct
        } else if let tiff = pasteboard.data(forType: .tiff),
                  let rep = NSBitmapImageRep(data: tiff) {
            png = rep.representation(using: .png, properties: [:])
        } else {
            png = nil
        }

        guard let data = png, !data.isEmpty, data.count <= maxImageBytes else { return nil }
        let rep = NSBitmapImageRep(data: data)
        return ClipboardPayload(
            kind: .image,
            imageData: data,
            pixelWidth: rep?.pixelsWide,
            pixelHeight: rep?.pixelsHigh,
            sourceApp: sourceApp,
            byteCount: data.count
        )
    }

    // MARK: - Source app

    private static func sourceAppName() -> String? {
        guard let app = NSWorkspace.shared.frontmostApplication,
              app.processIdentifier != ProcessInfo.processInfo.processIdentifier else { return nil }
        return app.localizedName
    }
}
